<script setup lang="ts">
import type { AnalysisConfig, AnalyticsExportStatus, AnalyticsExportType } from "~/types/analytics"
defineProps<{ modelValue: boolean; config: AnalysisConfig; status?: AnalyticsExportStatus | null; busy?: boolean }>()
const emit = defineEmits<{ (event: "close"): void; (event: "submit", type: AnalyticsExportType): void }>()
const type = ref<AnalyticsExportType>("aggregate_csv")
</script>
<template><div v-if="modelValue" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" role="dialog" aria-modal="true" aria-labelledby="export-title"><form class="w-full max-w-md rounded-lg bg-background p-5 shadow-xl" @submit.prevent="emit('submit',type)"><h2 id="export-title" class="text-lg font-bold">Ekspor privat</h2><p class="mt-2 text-sm">Filter aktif akan diterapkan pada data terbaru yang tersedia.</p><label class="mt-4 block text-sm font-medium">Format<select v-model="type" class="mt-1 h-10 w-full rounded-md border px-3"><option value="aggregate_csv">CSV agregat (langsung)</option><option value="detail_csv">CSV detail (maks. 50.000)</option><option value="aggregate_png">PNG agregat</option><option value="aggregate_pdf">PDF agregat</option></select></label><dl class="mt-3 grid grid-cols-2 gap-2 rounded-md bg-muted/40 p-3 text-xs"><div><dt class="text-muted-foreground">Masking</dt><dd>v1</dd></div><div><dt class="text-muted-foreground">Zona waktu</dt><dd>Asia/Jakarta</dd></div><div><dt class="text-muted-foreground">Batas detail</dt><dd>50.000 baris</dd></div><div><dt class="text-muted-foreground">Tautan</dt><dd>Privat, ≤24 jam</dd></div></dl><p class="mt-3 text-xs text-muted-foreground">Tautan privat kedaluwarsa paling lambat 24 jam.</p><div v-if="status" class="mt-3 rounded-md border p-2 text-sm" aria-live="polite">Status: {{ status.data.status === 'completed' ? 'Selesai' : status.data.status === 'queued' ? 'Menunggu' : status.data.status === 'processing' ? 'Diproses' : status.data.status === 'expired' ? 'Kedaluwarsa' : 'Gagal' }}<span v-if="status.data.estimatedRows"> · estimasi {{ status.data.estimatedRows.toLocaleString('id-ID') }} baris</span><a v-if="status.data.downloadUrl" class="ml-2 font-semibold underline" :href="status.data.downloadUrl">Unduh</a></div><div class="mt-4 flex justify-end gap-2"><button type="button" class="rounded-md border px-3 py-2" @click="emit('close')">Tutup</button><button type="submit" class="rounded-md bg-emerald-600 px-3 py-2 font-semibold text-white" :disabled="busy">{{ busy ? 'Menyiapkan…' : 'Mulai ekspor' }}</button></div></form></div></template>
